function s(v) { return String(v == null ? '' : v).trim(); }
function nz(x) { return s(x).toLowerCase().replace(/[^a-z0-9]/g, ''); }
const TODAY = '2026-09-15';
const inv = $('GET INVESTORS').first().json.values || [];
const pipe = $('GET PIPELINE').first().json.values || [];
if (inv.length < 200) { throw new Error('ABORT: INVESTORS only ' + inv.length); }
if (pipe.length < 500) { throw new Error('ABORT: PIPELINE only ' + pipe.length); }
const ih = (inv[0] || []).map(s);
const I = {}; ['investor','contact_person','email','sector','stage','cheque_inr_cr','do_not_contact'].forEach(function (n) { I[n] = ih.indexOf(n); if (I[n] < 0) { throw new Error('ABORT: INVESTORS missing ' + n); } });

// the second mandate row of each firm gets a name of its own; the FIRST row keeps the bare name
// so every existing PIPELINE row still resolves. Capital-A excluded (inactive, user 2026-09-15).
const PLAN = { accel: 'Accel - Seed Programme', yalicapital: 'Yali Capital - Defence & IP' };

const groups = {};
for (let r = 1; r < inv.length; r++) { const row = inv[r] || []; const n = s(row[I.investor]); if (!n) { continue; }
  const k = nz(n); if (!PLAN[k]) { continue; }
  (groups[k] = groups[k] || []).push({ row: r + 1, name: n, contact: s(row[I.contact_person]), email: s(row[I.email]).toLowerCase(),
    sector: s(row[I.sector]), stage: s(row[I.stage]), cheque: s(row[I.cheque_inr_cr]) }); }

const updates = [], renamed = [];
for (const k of Object.keys(PLAN)) { const g = groups[k];
  if (!g || g.length !== 2) { throw new Error('ABORT: expected exactly 2 rows for ' + k + ', found ' + (g ? g.length : 0)); }
  const emails = {}; g.forEach(function (x) { emails[x.email] = 1; });
  if (Object.keys(emails).length !== 1) { throw new Error('ABORT: ' + k + ' rows do not share one email: ' + JSON.stringify(Object.keys(emails)) + ' - renaming would risk sending to the wrong address'); }
  if (!g[0].email) { throw new Error('ABORT: ' + k + ' has no email'); }
  const second = g[1];
  if (nz(second.name) !== k) { throw new Error('ABORT: second row already renamed for ' + k + ': ' + second.name); }
  updates.push({ range: 'INVESTORS!A' + second.row, values: [[PLAN[k]]] });
  renamed.push({ firm: g[0].name, kept_row: g[0].row, kept_name: g[0].name, kept_thesis: g[0].sector + ' | ' + g[0].stage + ' | ' + g[0].cheque,
    renamed_row: second.row, new_name: PLAN[k], renamed_thesis: second.sector + ' | ' + second.stage + ' | ' + second.cheque,
    shared_email: g[0].email }); }
if (renamed.length !== 2) { throw new Error('ABORT: expected 2 renames, got ' + renamed.length); }

// Orphan check: compare BEFORE vs AFTER. Only block if THIS rename creates a new orphan.
// (East Ventures / Nirman Ventures are already orphaned - removed investors whose sent rows were dropped today.)
const before = {}, after = {};
for (let r = 1; r < inv.length; r++) { const row = inv[r] || []; const n = s(row[I.investor]); if (n) { before[n] = 1; after[n] = 1; } }
renamed.forEach(function (x) { after[x.new_name] = 1; });
const ph = (pipe[0] || []).map(s);
const P = {}; ['investor','deal_shared','pause'].forEach(function (n) { P[n] = ph.indexOf(n); });
const orphanBefore = {}, orphanAfter = {};
for (let r = 1; r < pipe.length; r++) { const row = pipe[r] || []; const n = s(row[P.investor]); if (!n) { continue; }
  if (s(row[P.pause]).toLowerCase() === 'yes') { continue; } // paused rows never send or follow up
  if (!before[n]) { orphanBefore[n] = (orphanBefore[n] || 0) + 1; }
  if (!after[n]) { orphanAfter[n] = (orphanAfter[n] || 0) + 1; } }
const newlyOrphaned = {};
for (const n of Object.keys(orphanAfter)) { if (!orphanBefore[n]) { newlyOrphaned[n] = orphanAfter[n]; } }
if (Object.keys(newlyOrphaned).length) { throw new Error('ABORT: this rename would newly orphan live PIPELINE rows: ' + JSON.stringify(newlyOrphaned)); }

return [{ json: { summary: { renames: renamed.length, cell_writes: updates.length,
  pre_existing_orphans: orphanBefore, newly_orphaned: 0 }, renamed: renamed, updates: updates } }];

function s(v) { return String(v == null ? '' : v).trim(); }
const plan = $('Plan').first().json;
const inv = $input.first().json.values || [];
const ih = (inv[0] || []).map(s);
const iN = ih.indexOf('investor'), iE = ih.indexOf('email');
const out = [];
let emailsOk = true;
plan.renamed.forEach(function (x) {
  const keptRow = inv[x.kept_row - 1] || [];
  const newRow = inv[x.renamed_row - 1] || [];
  const keptName = s(keptRow[iN]), newName = s(newRow[iN]);
  const keptMail = s(keptRow[iE]).toLowerCase(), newMail = s(newRow[iE]).toLowerCase();
  if (keptMail !== x.shared_email || newMail !== x.shared_email) { emailsOk = false; }
  out.push({ firm: x.firm, kept: keptName, kept_email: keptMail, renamed_to: newName, renamed_email: newMail,
    kept_thesis: x.kept_thesis, renamed_thesis: x.renamed_thesis,
    name_ok: keptName === x.kept_name && newName === x.new_name, email_unchanged: keptMail === x.shared_email && newMail === x.shared_email }); });
const wrote = $('Write renames').first().json || {};
return [{ json: { cells_updated: wrote.totalUpdatedCells || 0, all_emails_unchanged: emailsOk,
  results: out, ok: emailsOk && out.every(function (x) { return x.name_ok; }) } }];
